#!/usr/bin/env bun
// Bundle analysis for the start-up path. Usage:
//   bunx vite build --outDir /tmp/x/dist --emptyOutDir --sourcemap
//   bun scripts/perf/bundle.mjs /tmp/x/dist [chunk-name-prefix ...]
// Prints the files index.html loads before first paint (script, modulepreload,
// CSS) with raw and gzip sizes, the transitive static imports of the entry, and
// for each named chunk the bytes attributed to each package/source folder via
// its sourcemap (generated bytes per original source).
import { readFileSync, existsSync, readdirSync } from "node:fs";
import { join, basename } from "node:path";
import { gzipSync } from "node:zlib";

const dist = process.argv[2];
const focus = process.argv.slice(3);
const html = readFileSync(join(dist, "index.html"), "utf8");
const refs = [...html.matchAll(/(?:src|href)="\/(assets\/[^"]+)"/g)].map((m) => m[1]);

const kb = (n) => (n / 1024).toFixed(1).padStart(8) + " KiB";
const sizeOf = (p) => {
  const buf = readFileSync(join(dist, p));
  return { raw: buf.length, gz: gzipSync(buf).length };
};

// Static import closure (what the browser must fetch + evaluate before main runs).
const seen = new Set();
const queue = refs.filter((r) => r.endsWith(".js"));
while (queue.length) {
  const f = queue.shift();
  if (seen.has(f)) continue;
  seen.add(f);
  const src = readFileSync(join(dist, f), "utf8");
  // static imports only: `import ... from "./x.js"` / `import "./x.js"` at top level
  for (const m of src.matchAll(/(?:^|[;\n}])\s*import\s*(?:[^"'()]*?from\s*)?["'](\.\/[^"']+\.js)["']/g)) {
    queue.push("assets/" + basename(m[1]));
  }
}
const css = refs.filter((r) => r.endsWith(".css"));
let tRaw = 0, tGz = 0;
console.log("Start-up (index.html + static import closure):");
for (const f of [...seen, ...css]) {
  const s = sizeOf(f);
  tRaw += s.raw; tGz += s.gz;
  console.log(`  ${kb(s.raw)} ${kb(s.gz)} gz  ${f}`);
}
console.log(`  ${kb(tRaw)} ${kb(tGz)} gz  TOTAL`);
const fontRefs = new Set();
for (const f of css) for (const m of readFileSync(join(dist, f), "utf8").matchAll(/url\(\/?(assets\/[^)]+\.woff2)\)/g)) fontRefs.add(m[1]);
console.log(`  (${fontRefs.size} font files referenced by start-up CSS; only the faces used get fetched)`);

// Sourcemap attribution.
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const dec = Object.fromEntries([...B64].map((c, i) => [c, i]));
function attribute(file) {
  const mapPath = join(dist, file + ".map");
  if (!existsSync(mapPath)) return null;
  const map = JSON.parse(readFileSync(mapPath, "utf8"));
  const code = readFileSync(join(dist, file), "utf8").split("\n");
  const bytes = new Map();
  let srcIdx = 0;
  map.mappings.split(";").forEach((line, li) => {
    let col = 0;
    const segs = [];
    for (const seg of line.split(",")) {
      if (!seg) continue;
      const vals = [];
      let v = 0, shift = 0;
      for (const ch of seg) {
        const d = dec[ch];
        v += (d & 31) << shift;
        if (d & 32) shift += 5;
        else { vals.push(v & 1 ? -(v >>> 1) : v >>> 1); v = 0; shift = 0; }
      }
      col += vals[0];
      if (vals.length > 1) srcIdx += vals[1];
      segs.push([col, vals.length > 1 ? srcIdx : -1]);
      // remaining fields (line/col/name) are relative too but unused here
      if (vals.length > 2) {/* origLine */}
    }
    const len = (code[li] || "").length;
    segs.forEach(([c, s], i) => {
      const end = i + 1 < segs.length ? segs[i + 1][0] : len;
      const key = s < 0 ? "(unmapped)" : group(map.sources[s]);
      bytes.set(key, (bytes.get(key) || 0) + Math.max(0, end - c));
    });
  });
  return bytes;
}
function group(src) {
  const nm = src.lastIndexOf("node_modules/");
  if (nm >= 0) {
    const rest = src.slice(nm + 13).split("/");
    return "npm:" + (rest[0].startsWith("@") ? rest[0] + "/" + rest[1] : rest[0]);
  }
  const i = src.indexOf("src/");
  return i >= 0 ? src.slice(i).split("/").slice(0, 3).join("/") : src;
}
const targets = focus.length
  ? readdirSync(join(dist, "assets")).filter((f) => f.endsWith(".js") && focus.some((p) => f.startsWith(p))).map((f) => "assets/" + f)
  : [...seen];
for (const f of targets) {
  const b = attribute(f);
  if (!b) continue;
  const total = [...b.values()].reduce((a, c) => a + c, 0);
  console.log(`\n${f} (${kb(total)} mapped):`);
  [...b.entries()].sort((a, c) => c[1] - a[1]).slice(0, Number(process.env.TOP || 25)).forEach(([k, v]) => console.log(`  ${kb(v)}  ${k}`));
}
